// Config Clínica v3 — SEM catálogo hardcoded
// O catálogo vem do Supabase (public.exames)
const item = $input.item.json;

const clinic_profile = {
  brand_name:      'Bio Análise',
  legal_name:      'Pereira e Lima Análise Clínica Ltda',
  cnpj:            '12.234.310/0001-50',
  main_address:    'Av. Pará, nº 365, Centro, Iporá-GO',
  city:            'Iporá-GO',
  main_phone:      '(64) 3603-1306',
  main_whatsapp:   '(64) 3603-1306',
  corporate_email: 'bioanaliselab@bol.com.br',
  instagram:       'https://www.instagram.com/bioanaliseipora',
  // HORÁRIOS — somente coleta está validado pela clínica
  horario_coleta: {
    monday_to_friday: '06:30 às 16:00',
    saturday:         '07:00 às 09:00',
    sunday:           null,
    nota:             'Coleta de sangue e materiais biológicos'
  },
  horario_atendimento: null,   // não confirmado — não usar em respostas ao paciente
  horario_resultados:  null,   // não confirmado — encaminhar ao atendente se perguntado
  office_hours:        null,   // alias mantido null para compatibilidade; usar horario_coleta
  convenios: ['Caesan','Cassi','Celgmd','Vivacom','Itaú Saúde','Ipasgo','Postal Saúde','Bradesco Saúde','Saúde Caixa'],
  payment: {
    pix_key:      '64 98459 3264',
    pix_name:     'Bio Análise Laboratório',
    installments: 'Parcelamento sem juros: acima de R$ 400 em 2x | acima de R$ 600 em 3x.',
    cash: true,
    card: true
  },
  human_staff: [
    { name: 'Adriana', role: 'Atendente' },
    { name: 'Kaleb',   role: 'Atendente' },
    { name: 'Cida',    role: 'Atendente' }
  ],
  human_agents: ['Adriana','Kaleb','Cida'],
  base_greeting: 'Olá, aqui é da Bio Análise! Em que posso ajudar?'
};

// Alias de retrocompatibilidade temporário — remover após confirmar que
// nenhum trecho legado usa p.collection_hours
clinic_profile.collection_hours = clinic_profile.horario_coleta;

// Exames que NUNCA devem ser detalhados via bot — passar sempre para atendente
const restricted_topics = [
  'beta hcg','beta hcg qualitativo','beta hcg quantitativo',
  'hcg','sexagem fetal','dna','teste de paternidade','paternidade'
];

const handoff_templates = [
  'Esse atendimento precisa ser conduzido por um atendente da Bio Análise. Vou encaminhar sua solicitação para nossa equipe, tudo bem?',
  'Para garantir a orientação correta, vou encaminhar seu atendimento para a nossa equipe. Em breve entrarão em contato.',
  'Nossa equipe vai dar seguimento a esse atendimento. Aguarde, por favor.'
];

return [{ json: {
  ...item,
  clinic_profile,
  restricted_topics,
  handoff_templates,
  workflow_version: '3.2.0'
} }];

const base = $('Montar Base1').item.json;
const rawEvent = $input.item.json;
const data = rawEvent.data || {};
const key  = data.key  || {};
const msg  = data.message || {};
const messageType = data.messageType || 'unknown';

const remoteJid   = key.remoteJid || '';
const phoneRaw    = remoteJid.replace('@s.whatsapp.net','').replace('@g.us','');
const phoneNorm   = phoneRaw.replace(/\D/g,'');
const customerName = (data.pushName || 'Cliente WhatsApp').trim();

let messageText = '';
if (msg.conversation)                      messageText = msg.conversation;
else if (msg.extendedTextMessage)          messageText = msg.extendedTextMessage.text || '';
else if (msg.imageMessage)                 messageText = msg.imageMessage.caption || '';
else if (msg.documentMessage)              messageText = msg.documentMessage.caption || '';
else if (msg.videoMessage)                 messageText = msg.videoMessage.caption || '';
messageText = messageText.trim();

const isAudio    = ['audioMessage','pttMessage'].includes(messageType);
const isImage    = messageType === 'imageMessage';
const isDocument = messageType === 'documentMessage';
const isPdf      = isDocument && ((msg.documentMessage||{}).mimetype||'').toLowerCase().includes('pdf');

const mediaPayload = (isAudio || isImage || isDocument)
  ? { key, message: msg }
  : null;

const receivedAt = data.messageTimestamp
  ? new Date(data.messageTimestamp * 1000).toISOString()
  : new Date().toISOString();

const normalizedText = messageText.toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g,'')
  .trim();

return [{ json: {
  ...base,
  raw_event:        rawEvent,
  channel:          'whatsapp',
  evo_instance:     rawEvent.instance || '',
  phone_normalized: phoneNorm,
  phone_jid:        remoteJid,
  customer_name:    customerName,
  customer_phone:   '+' + phoneNorm,
  conversation_id:  'wa_' + phoneNorm,
  message_text:     messageText,
  normalized_text:  normalizedText,
  message_type:     messageType,
  is_audio:         isAudio,
  is_image:         isImage,
  is_document:      isDocument,
  is_pdf:           isPdf,
  media_payload:    mediaPayload,
  received_at:      receivedAt
} }];

const base       = $('Normalizar Entrada WhatsApp').item.json;
const configData = $('Montar Base1').item.json;
const parts      = (((($json||{}).candidates||[])[0]||{}).content||{}).parts||[];
const transcript = ((parts[0]||{}).text||'').trim();
const safe       = transcript || 'Não consegui transcrever o áudio. Pode enviar por texto, por favor?';

return [{ json: {
  ...base, ...configData,
  message_text:    safe,
  transcript_text: transcript || null,
  normalized_text: safe.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''),
  last_input_type: 'audio'
} }];

// Processa resposta da visão (imagem)
const base     = $('Normalizar Entrada WhatsApp').item.json;
const respNode = $input.item.json; // saída do Gemini Visao Imagem
let rawText = '';
try { rawText = respNode.candidates[0].content.parts[0].text || ''; } catch(e) {}
rawText = String(rawText || '').trim();

const splitPat = /\s*,\s*|\s*;\s*|\n+/;
let names = rawText.split(splitPat).map(e=>e.trim()).filter(Boolean);

// Normaliza compostos comuns
let normalized = [];
for (const exam of names) {
  const e = exam.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
  if (e.includes('tgo') && e.includes('tgp'))                                     { normalized.push('TGO','TGP'); }
  else if (e.includes('tsh') && e.includes('t4'))                                 { normalized.push('TSH','T4 Livre'); }
  else if (e.includes('ureia') && e.includes('creatinina'))                       { normalized.push('Ureia','Creatinina'); }
  else if (e.includes('colesterol total') && (e.includes('fracoes')||e.includes('frações'))) { normalized.push('Colesterol Total','HDL','LDL'); }
  else if (e.includes('urina tipo i') || (e.includes('eas') && e.length <= 5))    { normalized.push('EAS'); }
  else if (e.length >= 3)                                                          { normalized.push(exam); }
}

const unique = [...new Set(normalized.map(e=>e.trim()).filter(Boolean))];
const examsText = unique.join(', ');

const configData = $('Montar Base1').item.json;
const enriched = unique.length > 0
  ? `Tenho um pedido medico com os seguintes exames: ${examsText}. Quero saber o preparo e os valores.`
  : '[Imagem recebida — exames não identificados com segurança]';

const replyText = unique.length > 0
  ? `Recebi seu pedido médico! 🧬\n\nIdentifiquei os seguintes exames:\n${unique.map(e=>'• '+e).join('\n')}\n\nDeseja saber o *preparo*, os *valores* ou fazer o *agendamento*?`
  : `Recebi a imagem do seu pedido médico, mas não consegui identificar os exames com segurança. Vou encaminhar para um atendente, tudo bem?`;

return [{ json: {
  ...base,
  ...configData,
  message_text:         enriched,
  normalized_text:      enriched.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\w\s]/g,' ').trim(),
  image_exams_extracted: rawText,
  image_exams_list:     unique,
  image_context_active: unique.length > 0,
  last_input_type:      'image',
  is_image_request:     true,
  needs_human_review:   unique.length === 0,
  ai_reply_override:    replyText
} }];

// Processa resposta da visão para PDF — com fallback seguro
const base     = $('Normalizar Entrada WhatsApp').item.json;
const respNode = $input.item.json;
let rawText = '';
try { rawText = respNode.candidates[0].content.parts[0].text || ''; } catch(e) {}
rawText = String(rawText || '').trim();

// Heurísticas de baixa confiança
const UNCERTAINTY_PHRASES = [
  'não consigo','nao consigo','não é possível','ilegível','ilegivel',
  'não identificar','nao identificar','sem exames','qualidade insuficiente',
  'não consigo ler','imagem de baixa qualidade','sem informação'
];
const isLowConfidence =
  rawText.length === 0 ||
  rawText.length > 600 || // Gemini retornou texto demais — suspeito
  UNCERTAINTY_PHRASES.some(p => rawText.toLowerCase().includes(p));

if (isLowConfidence) {
  const configData = $('Montar Base1').item.json;
  return [{ json: {
    ...base,
    ...configData,
    message_text:       '[PDF recebido — processamento automático indisponível]',
    normalized_text:    'pdf recebido processamento automatico indisponivel',
    last_input_type:    'pdf',
    needs_human_review: true,
    pdf_fallback:       true,
    ai_reply_override:  'Recebi o seu PDF! Para garantir que todos os exames sejam identificados corretamente, vou encaminhar para um atendente revisar. Em breve entrarão em contato.',
    // Força handoff direto
    force_handoff:      true,
    force_handoff_category: 'pdf_review'
  } }];
}

// Processamento normal (igual ao de imagem)
const splitPat = /\s*,\s*|\s*;\s*|\n+/;
let names = rawText.split(splitPat).map(e=>e.trim()).filter(Boolean);
let normalized = [];
for (const exam of names) {
  const e = exam.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
  if (e.includes('tgo') && e.includes('tgp'))                                     { normalized.push('TGO','TGP'); }
  else if (e.includes('tsh') && e.includes('t4'))                                 { normalized.push('TSH','T4 Livre'); }
  else if (e.includes('ureia') && e.includes('creatinina'))                       { normalized.push('Ureia','Creatinina'); }
  else if (e.includes('colesterol total') && (e.includes('fracoes')||e.includes('frações'))) { normalized.push('Colesterol Total','HDL','LDL'); }
  else if (e.includes('urina tipo i') || (e.includes('eas') && e.length <= 5))    { normalized.push('EAS'); }
  else if (e.length >= 3)                                                          { normalized.push(exam); }
}
const unique = [...new Set(normalized.map(e=>e.trim()).filter(Boolean))];

if (unique.length === 0) {
  const configData = $('Montar Base1').item.json;
  return [{ json: {
    ...base, ...configData,
    last_input_type: 'pdf', needs_human_review: true, pdf_fallback: true,
    ai_reply_override: 'Não consegui identificar os exames no PDF enviado. Um atendente irá verificar manualmente.',
    force_handoff: true, force_handoff_category: 'pdf_review'
  } }];
}

const examsText  = unique.join(', ');
const configData = $('Montar Base1').item.json;
const enriched   = `Tenho um pedido medico com os seguintes exames: ${examsText}. Quero saber o preparo e os valores.`;
return [{ json: {
  ...base, ...configData,
  message_text: enriched,
  normalized_text: enriched.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\w\s]/g,' ').trim(),
  image_exams_extracted: rawText, image_exams_list: unique,
  image_context_active: true, last_input_type: 'pdf',
  ai_reply_override: `Recebi seu pedido (PDF)! 🧬\n\nExames identificados:\n${unique.map(e=>'• '+e).join('\n')}\n\nDeseja saber *preparo*, *valores* ou *agendamento*?`
} }];

const item = $input.item.json;
const text = (item.normalized_text || '').trim();
const restricted = item.restricted_topics || ['beta hcg','sexagem fetal','dna'];
const ctx = item.conversation_context || {};

const has = (terms) => terms.some(t => text.includes(t));

function norm(v) {
  return String(v || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[?.,!;:]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function cleanExamName(v) {
  return norm(v)
    .replace(/^exame de\s+/i, '')
    .replace(/^exame\s+/i, '')
    .replace(/^um exame de\s+/i, '')
    .replace(/^um exame\s+/i, '')
    .replace(/^o exame de\s+/i, '')
    .replace(/^o exame\s+/i, '')
    .trim();
}

function normalizeExamAliases(v) {
  const exam = cleanExamName(v);

  if (!exam) return exam;
  if (['urina simples', 'exame de urina simples', 'urina tipo 1', 'urina tipo i'].includes(exam)) return 'eas';
  if (exam === 'beta-hcg') return 'beta hcg';
  if (exam === 'rubela') return 'rubeola';
  if (exam === 't4l') return 't4 livre';
  if (exam === 'creatina') return 'creatinina';
  if (exam === 'cbc') return 'hemograma completo';
  if (exam === 'fosforo') return 'fosforo';

  return exam;
}

const GREETING_ONLY = [
  'oi','ola','olá','bom dia','boa tarde','boa noite','tudo bem','hey','e ai','e aí'
].map(norm);

const ACK_ONLY = [
  'ok','certo','entendi','sim','beleza','perfeito','otimo','ótimo','combinado','blz','show','recebi'
].map(norm);

const FAREWELL_ONLY = [
  'tchau','obrigado','obrigada','ate logo','até logo','valeu','muito obrigado','muito obrigada'
].map(norm);

const NON_EXAM_SHORT_MESSAGES = new Set([
  ...GREETING_ONLY,
  ...ACK_ONLY,
  ...FAREWELL_ONLY
]);

function looksLikeStandaloneExamCandidate(value) {
  const v = norm(value);
  if (!v) return false;

  if (NON_EXAM_SHORT_MESSAGES.has(v)) return false;

  const blocked = [
    'quero fazer',
    'preciso fazer',
    'gostaria de fazer',
    'valor',
    'preco',
    'preço',
    'orcamento',
    'orçamento',
    'agendamento',
    'agendar',
    'marcar',
    'preparo',
    'jejum',
    'prazo',
    'resultado',
    'endereco',
    'endereço',
    'telefone',
    'whatsapp',
    'instagram',
    'convenio',
    'convênio',
    'particular',
    'na verdade',
    'sao tres exames',
    'são três exames',
    'tres exames',
    'três exames'
  ].map(norm);

  if (blocked.includes(v)) return false;

  const knownShortExamForms = [
    't3','t4','tsh','vdrl','eas','epf','hcg','beta hcg',
    't3 livre','t4 livre','gama gt','tgo','tgp',
    'urina simples','urina tipo 1','urina tipo i',
    'calcio','cálcio','t4l','fosforo','fósforo'
  ].map(norm);

  if (knownShortExamForms.includes(v)) return true;

  if (v.length <= 2) return false;
  if (v.split(' ').length > 6) return false;

  return /^[a-z0-9\s\-]{2,50}$/.test(v);
}

function detectAgent() {
  const map = {
    adriana: 'Adriana',
    kaleby: 'Kaleby',
    kaleb: 'Kaleb',
    cida: 'Cida',
    'dr omar': 'Dr. Omar',
    'doutor omar': 'Dr. Omar',
    omar: 'Dr. Omar'
  };

  for (const [alias, name] of Object.entries(map)) {
    if (text.includes(alias)) return name;
  }

  return null;
}

function splitPotentialExams(value) {
  const raw = String(value || '').trim();
  if (!raw) return [];

  const parts = [];
  const lines = raw.replace(/\r/g, '\n').split('\n');

  for (const line of lines) {
    let cleaned = line.replace(/^[-•*]\s*/g, '').replace(/^\d+[.)-]?\s*/g, '').trim();

    // Strip conversational intent prefixes
    cleaned = cleaned.replace(/^(?:.*?)(?:quero|preciso|precisando|gostaria|vou)(?:.*?)(?:fazer|agendar|marcar|verificar)\s+/i, '');

    cleaned = cleaned.replace(/\b e \b/gi, ',');
    cleaned = cleaned.replace(/\b ou \b/gi, ',');

    cleaned.split(/\s*,\s*|\s*;\s*|\s*\/\s*|\s*\+\s*/g)
      .map(v => v.trim())
      .filter(Boolean)
      .forEach(v => {
        parts.push(v);

        // Extract what follows "exame de..." even if not at start
        const match = v.match(/(?:exames?\s+de\s+)(.+)/i);
        if (match && match[1]) {
          parts.push(match[1].trim());
        }

        const noPrefix = v.replace(/^(?:(?:um|uns|uma)\s+)?exames?\s+de\s+/i, '').replace(/^(?:o\s+)?exame\s+/i, '');
        if (noPrefix !== v) parts.push(noPrefix.trim());
      });
  }

  return [...new Set(
    parts
      .map(v => normalizeExamAliases(v))
      .filter(Boolean)
      .filter(looksLikeStandaloneExamCandidate)
  )];
}

function extractExamTerms() {
  const terms = new Set();
  const raw = String(item.message_text || item.mensagem_original || item.text || item.body || '').trim();
  const rawNorm = norm(raw);

  // 1) Linhas explícitas: "Exame de Ureia"
  raw
    .replace(/\r/g, '\n')
    .split('\n')
    .map(v => v.trim())
    .filter(Boolean)
    .forEach(line => {
      const cleanLine = line
        .replace(/^[-•*]\s*/g, '')
        .replace(/^\d+[.)-]?\s*/g, '')
        .trim();

      if (/^exame de /i.test(cleanLine) || /^exame /i.test(cleanLine)) {
        const cleaned = normalizeExamAliases(cleanLine);
        if (looksLikeStandaloneExamCandidate(cleaned)) {
          terms.add(cleaned);
        }
      }
    });

  // 2) Repetições "um exame de X, um exame de Y, um exame de Z"
  const repeatedExamRegex = /(?:(?:um|uns|uma)\s+)?exames?\s+de\s+([a-z\u00e0-\u00fa0-9\s\-\/\(\)]+?)(?=(?:,|\be\b|\bou\b|\n|$|(?:um|uns|uma)\s+exames?\s+de))/gi;
  for (const m of raw.matchAll(repeatedExamRegex)) {
    if (m[1]) {
      const cleaned = normalizeExamAliases(m[1]);
      if (looksLikeStandaloneExamCandidate(cleaned)) {
        terms.add(cleaned);
      }
    }
  }

  // 3) "quero fazer X, Y, Z"
  const listAfterIntentRegex = /(?:quero fazer|preciso fazer|gostaria de fazer|quero verificar|preciso verificar|gostaria de verificar)\s+(.+)/i;
  const intentMatch = raw.match(listAfterIntentRegex);
  if (intentMatch && intentMatch[1]) {
    splitPotentialExams(intentMatch[1]).forEach(term => {
      if (looksLikeStandaloneExamCandidate(term)) terms.add(term);
    });
  }

  // 4) Lista curta inteira
  if (rawNorm && rawNorm.length <= 220) {
    splitPotentialExams(raw).forEach(term => {
      if (looksLikeStandaloneExamCandidate(term)) terms.add(term);
    });
  }

  return [...terms];
}

// ── confirmação de exame ambíguo ─────────────────────────────
if (ctx.collect_field === 'confirmar_exame') {
  const options = Array.isArray(ctx.ambiguous_exam_options) ? ctx.ambiguous_exam_options : [];
  const inputNorm = norm(text);

  const matched = options.find(opt => {
    const optNorm = norm(opt);
    return optNorm === inputNorm || optNorm.includes(inputNorm) || inputNorm.includes(optNorm);
  });

  if (matched) {
    return [{
      json: {
        ...item,
        triage: {
          intent: ctx.last_intent === 'agendamento' ? 'agendamento' : 'consulta_exame',
          confidence: 0.99,
          urgency: 'normal',
          exam_name_raw: matched,
          exam_names_list: [matched],
          needs_human: false,
          requested_agent_name: null,
          reason_codes: ['ambiguous_exam_confirmed'],
          signals: {
            ambiguous_exam_confirmed: true
          }
        },
        conversation_context: {
          ...ctx,
          collect_field: null,
          ambiguous_exam_query: null,
          ambiguous_exam_options: []
        }
      }
    }];
  }

  return [{
    json: {
      ...item,
      triage: {
        intent: ctx.last_intent === 'agendamento' ? 'agendamento' : 'consulta_exame',
        confidence: 0.85,
        urgency: 'normal',
        exam_name_raw: text,
        exam_names_list: splitPotentialExams(text),
        needs_human: false,
        requested_agent_name: null,
        reason_codes: ['ambiguous_exam_confirmation_retry'],
        signals: {
          ambiguous_exam_confirmation_retry: true
        }
      }
    }
  }];
}

const hasImgCtx = Array.isArray(ctx.last_image_exams_list) && ctx.last_image_exams_list.length > 0;
const refersPrev = [
  'esses','esses exames','esses ai','esses aí','da imagem','do pedido','desses exames'
].includes(text);

if (refersPrev && hasImgCtx) {
  const examsText = ctx.last_image_exams_text || ctx.last_image_exams_list.join(', ');
  return [{
    json: {
      ...item,
      message_text: `Tenho um pedido medico com os seguintes exames: ${examsText}. Quero saber o preparo e os valores.`,
      normalized_text: `tenho um pedido medico com os seguintes exames ${examsText} quero saber o preparo e os valores`
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, ''),
      triage: {
        intent: 'preparo_e_valor',
        confidence: 0.96,
        urgency: 'normal',
        exam_name_raw: ctx.last_image_exams_list[0] || examsText,
        exam_names_list: ctx.last_image_exams_list,
        needs_human: false,
        requested_agent_name: null,
        reason_codes: ['image_ctx_reused'],
        signals: {}
      }
    }
  }];
}

const s = {
  mentions_restricted: has(restricted),
  asks_human: has([
    'quero falar com atendente','falar com atendente','chamar atendente',
    'atendimento humano','falar com alguem','falar com uma pessoa',
    'me passa para atendente','chama atendente'
  ]),
  asks_named_agent: Boolean(detectAgent()),
  complaint: has(['reclamacao','reclamar','insatisfeito','insatisfeita','pessimo','horrivel','vergonha']),
  asks_result: has(['resultado','ficou pronto','laudo','pegar resultado','meu resultado']),
  asks_schedule: has([
    'agendar','marcar','agenda','quero marcar','quero agendar','como agendar','horario disponivel'
  ]),
  asks_do_exam: has([
    'quero fazer exame','quero fazer um exame','fazer exame','fazer um exame',
    'quero fazer','preciso fazer exame','meu medico me passou','meu médico me passou'
  ]),
  asks_total_price: has([
    'valor total','preco total','total dos exames','quanto fica tudo',
    'total geral','valor final','qual o total','qual o total dos dois','soma dos exames'
  ]),
  asks_price: has([
    'preco','valor','custa','quanto custa','quanto e','qual o valor',
    'qual o preco','quanto fica','tabela de precos','valores dos exames','valor dos exames',
    'orcamento','orçamento'
  ]),
  asks_convenio: has([
    'convenio','plano de saude','plano','unimed','bradesco saude','aceita plano',
