};

const agent = detectAgent();

const extractedExamTerms = extractExamTerms();
const contextExamNamesList = Array.isArray(ctx.last_exam_names_list) ? ctx.last_exam_names_list : [];
const normalizedContextExamNamesList = contextExamNamesList.map(v => normalizeExamAliases(v)).filter(Boolean);

let exam_names_list = [...new Set(extractedExamTerms)];

if (!exam_names_list.length && hasImgCtx) {
  exam_names_list = [...new Set((ctx.last_image_exams_list || []).map(v => normalizeExamAliases(v)).filter(Boolean))];
}

const hasExamContext = Boolean(ctx.last_exam_name_raw) || normalizedContextExamNamesList.length > 0;
const examContextName = ctx.last_exam_name_raw || null;

const isDatePattern = /\d{1,2}[\/\-]\d{1,2}(?:[\/\-]\d{2,4})?/.test(text);
const isTimePattern = /\b\d{1,2}h\b|\b\d{1,2}:\d{2}\b/.test(text);
const isDayKeyword = /\b(segunda|terca|terça|terca-feira|terça-feira|quarta|quinta|sexta|sabado|sábado|domingo|amanha|amanhã|hoje|proxima|próxima|semana que vem)\b/.test(text);
const isShortReply = text.length > 0 && text.length <= 160;

const schedulingCollectFields = [
  'nome_completo',
  'nome_exame',
  'data_preferida',
  'horario_preferido',
  'tipo_coleta',
  'endereco_coleta',
  'telefone_contato',
  'confirmar_pedido_agendamento',
  'ajuste_pedido'
];

const explicitSchedulingContext =
  ctx.last_intent === 'agendamento' &&
  schedulingCollectFields.includes(ctx.collect_field || '') &&
  !s.mentions_restricted &&
  !s.complaint &&
  !s.asks_human &&
  !s.asks_named_agent &&
  !s.is_farewell;

const looksLikeDateOrTime =
  isDatePattern ||
  isTimePattern ||
  isDayKeyword;

const looksLikeExamReplyInScheduling =
  explicitSchedulingContext &&
  (ctx.collect_field === 'nome_exame') &&
  (
    exam_names_list.length > 0 ||
    hasExamContext
  );

const shouldStayInScheduling =
  explicitSchedulingContext &&
  (
    looksLikeDateOrTime ||
    s.is_ack ||
    looksLikeExamReplyInScheduling ||
    (isShortReply && !s.asks_price && !s.asks_prep && !s.asks_turnaround)
  );

const isExamFollowUp =
  hasExamContext &&
  !s.asks_schedule &&
  !s.asks_collection_home &&
  !explicitSchedulingContext &&
  !s.mentions_restricted &&
  !s.complaint &&
  !s.asks_human &&
  !s.asks_named_agent &&
  (
    s.asks_price ||
    s.asks_prep ||
    s.asks_total_price ||
    s.asks_turnaround ||
    text === 'qual o valor' ||
    text === 'valor' ||
    text === 'preco' ||
    text === 'preço' ||
    text === 'qual o preparo' ||
    text === 'precisa de jejum' ||
    text === 'tem jejum' ||
    text === 'qual o prazo'
  );

if (looksLikeExamReplyInScheduling) {
  return [{
    json: {
      ...item,
      triage: {
        intent: 'agendamento',
        confidence: 0.98,
        urgency: 'normal',
        exam_name_raw: exam_names_list[0] || examContextName || normalizedContextExamNamesList[0] || null,
        exam_names_list: exam_names_list.length ? exam_names_list : (normalizedContextExamNamesList.length ? normalizedContextExamNamesList : (examContextName ? [examContextName] : [])),
        needs_human: false,
        requested_agent_name: null,
        reason_codes: ['scheduling_exam_reply'],
        signals: {
          ...s,
          scheduling_exam_reply: true
        }
      }
    }
  }];
}

if (isExamFollowUp) {
  let followIntent = 'valor';

  if (s.asks_prep && s.asks_price) followIntent = 'preparo_e_valor';
  else if (s.asks_prep) followIntent = 'preparo_exame';
  else if (s.asks_total_price) followIntent = 'valor_total';
  else if (s.asks_turnaround) followIntent = 'prazo';
  else if (s.asks_price) followIntent = 'valor';

  return [{
    json: {
      ...item,
      triage: {
        intent: followIntent,
        confidence: 0.97,
        urgency: 'normal',
        exam_name_raw: examContextName || normalizedContextExamNamesList[0] || null,
        exam_names_list: normalizedContextExamNamesList.length ? normalizedContextExamNamesList : (examContextName ? [examContextName] : []),
        needs_human: false,
        requested_agent_name: null,
        reason_codes: ['exam_context_follow_up'],
        signals: {
          ...s,
          exam_context_follow_up: true
        }
      }
    }
  }];
}

const reasons = [];
let intent = 'desconhecido';
let conf = 0.55;

const asksHomeCollectionAndSchedule =
  s.asks_collection_home &&
  (s.asks_schedule || looksLikeDateOrTime || has(['quero','preciso','gostaria']));

const mixedPriceAndSchedule =
  (s.asks_price || s.asks_total_price) &&
  (s.asks_schedule || looksLikeDateOrTime);

if (s.mentions_restricted) {
  intent = 'restrito';
  conf = 0.99;
  reasons.push('restricted_topic');
}
else if (s.complaint) {
  intent = 'reclamacao';
  conf = 0.97;
  reasons.push('complaint');
}
else if (s.asks_human || s.asks_named_agent) {
  intent = 'humano';
  conf = 0.96;
  reasons.push('human_requested');
  if (agent) reasons.push('named_agent');
}
else if (s.unsure_exam) {
  intent = 'duvida_nome_exame';
  conf = 0.92;
  reasons.push('exam_name_uncertain');
}
else if (s.asks_result) {
  intent = 'resultado';
  conf = 0.93;
  reasons.push('result_detected');
}
else if (shouldStayInScheduling) {
  intent = 'agendamento';
  conf = 0.98;
  reasons.push('scheduling_ctx_follow_up');
}
else if (ctx.last_intent === 'coleta_domiciliar' && (s.is_ack || s.asks_schedule || s.asks_do_exam || has(['quero', 'pode sim', 'pode seguir']))) {
  intent = 'agendamento';
  conf = 0.95;
  reasons.push('agendamento_from_info');
}
else if (asksHomeCollectionAndSchedule) {
  intent = 'agendamento';
  conf = 0.97;
  reasons.push('home_collection_schedule');
}
else if (s.asks_collection_home) {
  intent = 'coleta_domiciliar';
  conf = 0.97;
  reasons.push('home_collection_info');
}
else if (mixedPriceAndSchedule) {
  intent = 'agendamento';
  conf = 0.96;
  reasons.push('mixed_price_and_schedule');
}
else if (s.asks_schedule) {
  intent = 'agendamento';
  conf = 0.92;
  reasons.push('scheduling');
}
else if (s.asks_prep && s.asks_total_price) {
  intent = 'preparo_e_valor_total';
  conf = 0.95;
  reasons.push('prep_and_total');
}
else if (s.asks_total_price) {
  intent = 'valor_total';
  conf = 0.94;
  reasons.push('total_price');
}
else if (s.asks_prep && s.asks_price) {
  intent = 'preparo_e_valor';
  conf = 0.93;
  reasons.push('prep_and_price');
}
else if (s.asks_generic_blood_fasting) {
  intent = 'preparo_generico_sangue';
  conf = 0.95;
  reasons.push('generic_blood_fasting');
}
else if (s.asks_prep) {
  intent = 'preparo_exame';
  conf = 0.90;
  reasons.push('prep');
}
else if (s.asks_price) {
  intent = 'valor';
  conf = 0.92;
  reasons.push('price');
}
else if (s.asks_turnaround) {
  intent = 'prazo';
  conf = 0.86;
  reasons.push('turnaround');
}
else if (s.asks_convenio) {
  intent = 'convenio';
  conf = 0.91;
  reasons.push('insurance');
}
else if (s.asks_hours) {
  intent = 'horario';
  conf = 0.94;
  reasons.push('hours');
}
else if (s.asks_address) {
  intent = 'endereco';
  conf = 0.93;
  reasons.push('address');
}
else if (s.asks_contact || s.asks_catalog || s.asks_collection) {
  intent = 'institucional';
  conf = 0.92;
  reasons.push('institutional');
}
else if (exam_names_list.length > 0 && (s.asks_do_exam || text.length <= 220)) {
  intent = explicitSchedulingContext ? 'agendamento' : 'consulta_exame';
  conf = exam_names_list.length > 1 ? 0.96 : 0.91;
  reasons.push(explicitSchedulingContext ? 'scheduling_exam_continuation' : (exam_names_list.length > 1 ? 'multi_exam_query' : 'direct_exam_query'));
}
else if (s.is_greeting || s.is_ack) {
  intent = 'saudacao';
  conf = 0.95;
  reasons.push('greeting');
}
else if (s.is_farewell) {
  intent = 'despedida';
  conf = 0.94;
  reasons.push('farewell');
}
else if (isShortReply && explicitSchedulingContext && looksLikeDateOrTime) {
  intent = 'agendamento';
  conf = 0.88;
  reasons.push('scheduling_short_follow_up');
}

if (exam_names_list.length > 0) {
  reasons.push('exam_names_extracted');
}

const exam_name_raw =
  exam_names_list[0] ||
  examContextName ||
  normalizedContextExamNamesList[0] ||
  null;

const final_exam_names_list =
  exam_names_list.length > 0
    ? exam_names_list
    : (
        normalizedContextExamNamesList.length > 0
          ? normalizedContextExamNamesList
          : (examContextName ? [examContextName] : [])
      );

const needs_human =
  s.mentions_restricted ||
  s.complaint ||
  s.asks_human ||
  s.asks_named_agent ||
  s.unsure_exam ||
  s.asks_result;

return [{
  json: {
    ...item,
    triage: {
      intent,
      confidence: conf,
      urgency: s.complaint ? 'high' : 'normal',
      exam_name_raw,
      exam_names_list: final_exam_names_list,
      needs_human,
      requested_agent_name: agent,
      reason_codes: reasons,
      signals: {
        ...s,
        multi_exam_detected: final_exam_names_list.length > 1,
        home_collection_detected: s.asks_collection_home
      }
    }
  }
}];

const item = $input.first().json || {};
const triage = item.triage || {};

let intent = triage.intent || 'desconhecido';
let confidence = typeof triage.confidence === 'number' ? triage.confidence : 0.75;
let decision = 'answer';
let target_agent = 'institutional_agent';
let clarification_question = null;
let requested_agent_name = triage.requested_agent_name || null;
let reason_codes = Array.isArray(triage.reason_codes) ? [...triage.reason_codes] : [];

const needsHuman = Boolean(triage.needs_human || triage.requiresHuman);

if (needsHuman) {
  decision = 'handoff';
  target_agent = null;
  reason_codes.push('triage_requested_handoff');
} else if (intent === 'desconhecido') {
  decision = 'clarify';
  target_agent = null;
  clarification_question = 'Posso te ajudar com exames, preparo, valores, agendamento, horários ou endereço. O que você deseja?';
  reason_codes.push('unknown_intent');
} else if ([
  'saudacao',
  'despedida',
  'horario',
  'endereco',
  'institucional',
  'convenio',
  'cadastro',
  'coleta',
  'coleta_domiciliar'
].includes(intent)) {
  decision = 'answer';
  target_agent = 'institutional_agent';
  reason_codes.push('route_institutional');
} else if ([
  'consulta_exame',
  'preparo_exame',
  'preparo_e_valor',
  'preparo_e_valor_total',
  'valor',
  'valor_total',
  'prazo',
  'orcamento'
].includes(intent)) {
  decision = 'answer';
  target_agent = 'exam_prep_agent';
  reason_codes.push('route_exam_prep');
} else if (['agendamento'].includes(intent)) {
  decision = 'answer';
  target_agent = 'scheduling_agent';
  reason_codes.push('route_scheduling');
} else {
  decision = 'answer';
  target_agent = 'institutional_agent';
  reason_codes.push('route_default_institutional');
}

return [{
  json: {
    ...item,
    orchestration: {
      intent,
      decision,
      target_agent,
      confidence,
      clarification_question,
      requested_agent_name,
      reason_codes
    }
  }
}];

const item      = $input.item.json;
const templates = item.handoff_templates || ['Esse atendimento precisa ser conduzido por um atendente da Bio Análise. Vou encaminhar sua solicitação, tudo bem?'];
const orch      = item.orchestration || {};
const t         = item.triage || {};
const reasons   = orch.reason_codes || [];

let cat = 'general_handoff';
if (reasons.some(r=>r.includes('restricted')))   cat='restricted_exam';
else if (reasons.some(r=>r.includes('complaint'))) cat='complaint';
else if (reasons.some(r=>r.includes('result')))  cat='exam_result';
else if (reasons.some(r=>r.includes('human')))   cat='human_request';
else if (reasons.some(r=>r.includes('unsure')))  cat='exam_name_unclear';
else if (reasons.some(r=>r.includes('pdf')))     cat='pdf_review';

const idx = String(item.phone_normalized||'0').split('').reduce((a,c)=>a+c.charCodeAt(0),0) % templates.length;

const handoff_record = {
  conversation_id:  item.conversation_id,
  created_at:       new Date().toISOString(),
  patient_name:     item.customer_name || null,
  patient_phone:    item.customer_phone || null,
  canal:            'whatsapp',
  categoria:        cat,
  reason_codes:     reasons,
  agente_solicitado: orch.requested_agent_name || t.requested_agent_name || null,
  status:           'pending'
};

return [{ json: { ...item, handoff_record, response: {
  status: 'handoff_ready', subagent: 'human_handoff_agent',
  reply: templates[idx], handoff: true, handoff_category: cat,
  queue_tags: ['human_handoff', cat], reason_codes: reasons
} } }];

const item = $input.item.json || {};
const p = item.clinic_profile || {};
const t = item.triage || {};
const orch = item.orchestration || {};
const ctx = item.conversation_context || {};

const finalIntent = orch.intent || t.intent || null;

const primeiroNome =
  item.customer_name &&
  item.customer_name !== 'Cliente WhatsApp'
    ? item.customer_name.split(' ')[0]
    : null;

const nome = primeiroNome ? `, ${primeiroNome}` : '';

const textoOriginal = String(item.message_text || '').trim();
const texto = textoOriginal
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();

function saudacaoHorario() {
  const agora = new Date();
  const hora = agora.getHours();

  if (hora >= 5 && hora < 12) return 'Bom dia';
  if (hora >= 12 && hora < 18) return 'Boa tarde';
  return 'Boa noite';
}

const cumprimento = saudacaoHorario();

const conversaEmAndamento =
  Boolean(ctx.last_intent) &&
  !['saudacao', 'despedida'].includes(ctx.last_intent || '');

function respostaSaudacao() {
  if (texto.includes('bom dia')) {
    return `Bom dia${nome}! Aqui é da *Bio Análise* 🧬\n\nComo posso te ajudar hoje?`;
  }

  if (texto.includes('boa tarde')) {
    return `Boa tarde${nome}! Aqui é da *Bio Análise* 🧬\n\nComo posso te ajudar hoje?`;
  }

  if (texto.includes('boa noite')) {
    return `Boa noite${nome}! Aqui é da *Bio Análise* 🧬\n\nComo posso te ajudar hoje?`;
  }

  if (conversaEmAndamento) {
    return `Olá${nome}! Como posso te ajudar agora?`;
  }

  return `${cumprimento}${nome}! Aqui é da *Bio Análise* 🧬\n\nComo posso te ajudar hoje?`;
}

function respostaDespedida() {
  return `Nós que agradecemos${nome}. Ficamos à disposição sempre que precisar. 🧬`;
}

function getHorarioColeta() {
  const hc = p.horario_coleta || {};
  return {
    seg: hc.monday_to_friday || '06:30 às 16:00',
    sab: hc.saturday || '07:00 às 09:00',
    dom: hc.sunday || null
  };
}

function getAmanhaInfo() {
  const agora = new Date();
  const amanha = new Date(agora);
  amanha.setDate(agora.getDate() + 1);
  return amanha.getDay();
}

function respostaHorario() {
  const { seg, sab } = getHorarioColeta();

  if (
    texto.includes('domingo') &&
    (texto.includes('fechado') || texto.includes('abre') || texto.includes('funciona'))
  ) {
    return `Sim, aos domingos a Bio Análise está fechada.`;
  }

  if (texto.includes('amanha') || texto.includes('amanhã')) {
    const dia = getAmanhaInfo();

    if (dia === 0) {
      return `Amanhã, domingo, a Bio Análise estará fechada.`;
    }

    if (dia === 6) {
      return `Amanhã, sábado, o horário de coleta será das *${sab}*.`;
    }

    return `Amanhã, o horário de coleta será das *${seg}*.`;
  }

  if (texto.includes('sabado') || texto.includes('sábado')) {
    return `Aos sábados, o horário de coleta da Bio Análise é das *${sab}*.`;
  }

  if (
    texto.includes('segunda') ||
    texto.includes('terca') ||
    texto.includes('terça') ||
    texto.includes('quarta') ||
    texto.includes('quinta') ||
    texto.includes('sexta')
  ) {
    return `De segunda a sexta, o horário de coleta da Bio Análise é das *${seg}*.`;
  }

  return `Os *horários de coleta* da Bio Análise são:\n• Segunda a sexta: ${seg}\n• Sábado: ${sab}\n• Domingo: fechado\n\n📍 ${p.main_address || 'Av. Pará, nº 365, Centro, Iporá-GO'}\n📞 ${p.main_phone || '(64) 3603-1306'}`;
}

function respostaEndereco() {
  return `A *Bio Análise* fica em:\n📍 ${p.main_address || 'Av. Pará, nº 365, Centro, Iporá-GO'}\n\n📞 ${p.main_phone || '(64) 3603-1306'}\n\nSe quiser, também posso te informar os horários de coleta.`;
}

function respostaContato() {
  return `Esses são os canais de contato da *Bio Análise*:\n📞 Telefone / WhatsApp: ${p.main_phone || '(64) 3603-1306'}\n📧 E-mail: ${p.corporate_email || 'bioanaliselab@bol.com.br'}\n📍 Endereço: ${p.main_address || 'Av. Pará, nº 365, Centro, Iporá-GO'}`;
}

function respostaConvenio() {
  const convenios = Array.isArray(p.convenios) ? p.convenios : [];

