}

function respostaColetaDomiciliar() {
  const { seg, sab } = getHorarioColeta();

  const fazDomicilio = true;

  if (!fazDomicilio) {
    return `No momento, a Bio Análise não realiza coleta domiciliar. As coletas são feitas na unidade, nos seguintes horários:\n• Segunda a sexta: *${seg}*\n• Sábado: *${sab}*`;
  }

  const querAgendar =
    texto.includes('agendar') ||
    texto.includes('marcar') ||
    texto.includes('quero') ||
    texto.includes('preciso');

  const replyBase =
    `A Bio Análise *realiza coleta domiciliar*, mediante *agendamento prévio*.\n\n` +
    `📌 Como funciona:\n` +
    `• a solicitação precisa ser confirmada pela equipe;\n` +
    `• avaliamos disponibilidade de agenda;\n` +
    `• confirmamos os exames solicitados, endereço e melhor horário;\n` +
    `• os horários seguem nossa janela de coleta.\n\n` +
    `🕒 Horários de coleta:\n` +
    `• Segunda a sexta: *${seg}*\n` +
    `• Sábado: *${sab}*\n` +
