const active = item.subagente || item.active_subagent || orch.target_agent || 'institutional_agent';
const p = item.clinic_profile || {};
const ctx = item.conversation_context || {};
const greeting = item.greeting_analysis || {};
const temporal = item.temporal_context || {};

// Mensagem do cliente
const customerMessage =
  item.mensagem_original ||
  item.message_text ||
  item.message ||
  item.text ||
  item.body ||
  item.content ||
  '';

// Prompt especializado do subagente
const subagentPrompt = item.prompt_sistema || '';
const contextGoal = item.llm_context_goal || item.groq_context_goal || '';

// Temperatura
let temp = 0.2;
if (orch.intent === 'saudacao' || orch.intent === 'despedida') temp = 0.4;

// Regra de preço
const priceRule =
  active === 'exames_preparo' || active === 'exam_prep_agent'
    ? 'Você PODE informar valores particulares quando disponíveis em safe_data.'
    : 'Não informe preços de exames nesta resposta, a menos que eles já estejam estruturados em safe_data.price_summary ou ai_reply_override.';

// Prompt global
const baseSystemPrompt = `
Você é o assistente virtual da ${p.brand_name || 'Bio Análise'}, clínica de análises clínicas em ${p.city || 'Iporá-GO'}.

ESTILO DE RESPOSTA:
- Fale como uma atendente humana, cordial, natural e profissional.
- Seja acolhedora, clara e objetiva, sem parecer robótica.
- Use linguagem fluida de WhatsApp.
- Evite repetir sempre a mesma estrutura de resposta.
- Use *negrito* apenas quando fizer sentido para destacar exame, valor ou informação importante.

REGRAS GLOBAIS:
1. Use SOMENTE os dados de safe_data e do contexto recebido. Nunca invente informações.
2. ${priceRule}
3. Nunca forneça detalhes sobre Beta HCG, sexagem fetal, DNA ou teste de paternidade. Nesses casos, encaminhe para atendente.
4. Quando faltar informação, peça de forma simples e natural.
5. Para agendamento, informe sempre que ele é provisório e será confirmado pela equipe.
6. Para cadastro, quando necessário, peça um dado por vez.
7. Quando o paciente pedir valor de exame, informe diretamente se houver valor disponível.
8. Quando o paciente pedir preparo + valor, entregue os dois de forma organizada e natural.
9. Quando o paciente pedir agendamento, conduza a coleta progressiva dos dados sem soar mecânica.
10. Nunca invente convênio, prazo, endereço, horário ou valor fora do safe_data.
11. Sempre responda em português do Brasil.
12. Se a conversa já estiver em andamento, não repita saudação longa desnecessariamente.
13. Nunca trate pergunta sobre exame como assunto institucional.
14. Nunca responda com contatos institucionais se o cliente estiver perguntando sobre exame.
15. Se existir ai_reply_override, considere isso como a resposta prioritária e não contradiga essa instrução.
16. Se o collect_field estiver preenchido, entenda que a conversa está em coleta guiada e respeite a etapa atual.
17. Se houver orçamento em andamento, use budget_exam_names_list, budget_resolved_exams e budget_total_snapshot como fonte oficial.
18. Nunca misture texto livre do cliente com o nome dos exames no resumo final.

REGRA DE SAUDAÇÃO:
- Se o cliente usar "bom dia", responda "Bom dia".
- Se usar "boa tarde", responda "Boa tarde".
- Se usar "boa noite", responda "Boa noite".
- Priorize espelhar a saudação do cliente em vez de corrigi-la pelo horário.
- Só use saudação baseada no horário quando o cliente não tiver cumprimentado.

REGRAS DE HORÁRIO E FUNCIONAMENTO:
- Perguntas sobre hoje, amanhã, domingo, sábado, dias da semana, horário, abertura, funcionamento, atendimento ou coleta devem ser tratadas como assunto institucional.
- Nunca trate essas mensagens como pergunta de exame.
- Use temporal_context como fonte de verdade para interpretar "hoje" e "amanhã".
- Se temporal_context.horario_amanha.aberto for false, responda de forma direta.
- Se a pergunta for objetiva sobre um dia específico, responda primeiro de forma direta e curta.

FORMATO DE SAÍDA:
Você deve responder obrigatoriamente em json válido.
Retorne apenas json puro, sem markdown, sem explicações e sem texto fora do json.
Use exatamente esta estrutura json:
{"status":"answered"|"need_clarification"|"handoff","reply":"texto","handoff":false,"handoff_category":null,"reason_codes":[]}
`;

// Prompt final
const developerPrompt = [
  baseSystemPrompt.trim(),
  contextGoal ? '\n\nOBJETIVO OPERACIONAL:\n' + contextGoal.trim() : '',
  subagentPrompt ? '\n\nREGRAS ESPECÍFICAS DO SUBAGENTE:\n' + subagentPrompt.trim() : ''
].join('');

// Payload do usuário
const payload = {
  customer_message: customerMessage,
  customer_name: item.customer_name || ctx.paciente_nome || 'Cliente',
  customer_phone: ctx.customer_phone || item.customer_phone || null,

  intent: orch.intent || null,
  decision: orch.decision || null,
  target_agent: orch.target_agent || active,
  active_subagent: active,

  ai_reply_override: item.ai_reply_override || null,

  safe_data: item.safe_data || {},
  temporal_context: temporal || null,
  greeting_analysis: greeting || null,

  subagent_signals: {
    parece_consulta_exame: item.parece_consulta_exame ?? null,
    precisa_confirmacao: item.precisa_confirmacao ?? null,
    eh_restrito: item.eh_restrito ?? null,
    mensagem_normalizada: item.mensagem_normalizada || null
  },

  conversation_context: {
    last_intent: ctx.last_intent || null,
    current_status: ctx.current_status || null,
    last_exam_name_raw: ctx.last_exam_name_raw || null,
    last_exam_names_list: ctx.last_exam_names_list || [],
    last_input_type: ctx.last_input_type || null,

    collect_field: ctx.collect_field || null,
    agendamento_etapa: ctx.agendamento_etapa || null,

    tipo_coleta: ctx.tipo_coleta || null,
    endereco_coleta: ctx.endereco_coleta || null,
    data_preferida: ctx.data_preferida || null,
    horario_preferido: ctx.horario_preferido || null,

    budget_mode_active: ctx.budget_mode_active ?? null,
    budget_exam_names_list: ctx.budget_exam_names_list || [],
    budget_resolved_exams: ctx.budget_resolved_exams || [],
    budget_total_snapshot: ctx.budget_total_snapshot || null,
    budget_payment_type: ctx.budget_payment_type || null
  },

  operational_rules: {
    if_restricted_exam: 'status=handoff',
    if_exam_ambiguous: 'status=need_clarification',
    if_exam_identified: 'status=answered',
    if_hours_question_about_tomorrow_and_closed: 'status=answered',
    if_greeting_present: 'mirror_customer_greeting',
    if_ai_reply_override_exists: 'respect_override'
  },

  output_requirement: 'Responder em json válido, puro, sem texto extra.'
};

return [{
  json: {
    ...item,
    openai_request: {
      model: 'gpt-4.1-mini',
      temperature: temp,
      max_completion_tokens: 450,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: developerPrompt },
        { role: 'user', content: JSON.stringify(payload) }
      ]
    }
  }
}];

const base = $('Preparar Payload OpenAI').item.json || {};
const raw = (((($json.choices || [])[0] || {}).message || {}).content) || '';

let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  parsed = {
    status: 'answered',
    reply: base.orchestration?.clarification_question ||
      'Posso te ajudar com horários, endereço, preparo, valores e agendamento.',
    handoff: false,
    handoff_category: null,
    reason_codes: []
  };
}

const forcedReply = base.ai_reply_override || null;
const forcedStatus =
  base.force_response_status ||
  (base.force_handoff ? 'handoff_ready' : null);

const finalStatus =
  forcedStatus ||
  parsed.status ||
  'answered';

const finalHandoff =
  Boolean(base.force_handoff) ||
  Boolean(parsed.handoff);

const finalCategory =
  base.force_handoff_category ||
  parsed.handoff_category ||
  null;

return [{
  json: {
    ...base,
    handoff_record: base.handoff_record || null,
    response: {
      status: finalStatus,
      subagent: (base.orchestration && base.orchestration.target_agent) || base.active_subagent || 'openai_writer',
      reply: forcedReply || parsed.reply || 'Posso ajudar com horário, endereço e exames da Bio Análise.',
      handoff: finalHandoff,
      handoff_category: finalCategory,
      queue_tags: finalHandoff ? ['human_handoff', finalCategory || 'general_handoff'] : [],
      reason_codes: (
        Array.isArray(parsed.reason_codes) && parsed.reason_codes.length
          ? parsed.reason_codes
          : ((base.orchestration && base.orchestration.reason_codes) || [])
      )
    }
  }
}];

const item = $input.item.json;
const resp = item.response || {};
const orch = item.orchestration || {};
const t = item.triage || {};
const ctx = item.conversation_context || {};
const safeData = item.safe_data || {};

let status = 'answered_by_ai';
if (resp.handoff) status = 'awaiting_human';
else if (resp.status === 'need_clarification') status = 'awaiting_customer';
else if (resp.status === 'handoff_ready') status = 'awaiting_human';

const quotedExams =
  Array.isArray(safeData.exams)
    ? safeData.exams
    : (ctx.last_quoted_exams || []);

const examNamesFromSafeData =
  Array.isArray(safeData.exam_names_list) && safeData.exam_names_list.length
    ? safeData.exam_names_list
    : (
        Array.isArray(safeData.exames) && safeData.exames.length
          ? safeData.exames.map(e => e.nome).filter(Boolean)
          : []
      );

const examNamesFromTriage =
  Array.isArray(t.exam_names_list) && t.exam_names_list.length
    ? t.exam_names_list
    : [];

const examNamesFromConversation =
  Array.isArray((item.conversation_context || {}).last_exam_names_list) &&
  (item.conversation_context || {}).last_exam_names_list.length
    ? (item.conversation_context || {}).last_exam_names_list
    : [];

const examNamesFromContext =
  Array.isArray(ctx.last_exam_names_list)
    ? ctx.last_exam_names_list
    : [];

const finalExamNamesList =
  examNamesFromSafeData.length
    ? examNamesFromSafeData
    : (
        examNamesFromConversation.length
          ? examNamesFromConversation
          : (
              examNamesFromTriage.length
                ? examNamesFromTriage
                : examNamesFromContext
            )
      );

// ==============================
// CAMPOS DE ORÇAMENTO
// ==============================
const budgetExamNamesFromSafe =
  Array.isArray(safeData.budget_exam_names_list) && safeData.budget_exam_names_list.length
    ? safeData.budget_exam_names_list
    : [];

const budgetExamNamesFromConversation =
  Array.isArray((item.conversation_context || {}).budget_exam_names_list) &&
  (item.conversation_context || {}).budget_exam_names_list.length
    ? (item.conversation_context || {}).budget_exam_names_list
    : [];

const budgetExamNamesFromContext =
  Array.isArray(ctx.budget_exam_names_list)
    ? ctx.budget_exam_names_list
    : [];

const finalBudgetExamNamesList =
  budgetExamNamesFromSafe.length
    ? budgetExamNamesFromSafe
    : (
        budgetExamNamesFromConversation.length
          ? budgetExamNamesFromConversation
          : (
              finalExamNamesList.length
                ? finalExamNamesList
                : budgetExamNamesFromContext
            )
      );

const budgetResolvedExamsFromSafe =
  Array.isArray(safeData.budget_resolved_exams) && safeData.budget_resolved_exams.length
    ? safeData.budget_resolved_exams
    : (
        Array.isArray(safeData.exames) && safeData.exames.length
          ? safeData.exames
          : []
      );

const budgetResolvedExamsFromContext =
  Array.isArray(ctx.budget_resolved_exams)
    ? ctx.budget_resolved_exams
    : [];

const finalBudgetResolvedExams =
  budgetResolvedExamsFromSafe.length
    ? budgetResolvedExamsFromSafe
    : budgetResolvedExamsFromContext;

let budgetTotalFromSafe = safeData.budget_total_snapshot ?? null;

if (
  budgetTotalFromSafe === null &&
  typeof safeData.price_summary === 'string'
) {
  const match = safeData.price_summary.match(/Valor total:\s*R\$\s*([\d.,]+)/i);
  if (match && match[1]) {
    budgetTotalFromSafe = `R$ ${match[1].replace(/^R\$\s*/i, '')}`;
  }
}

const budgetTotalSnapshot =
  budgetTotalFromSafe ??
  (item.conversation_context || {}).budget_total_snapshot ??
  ctx.budget_total_snapshot ??
  null;

const budgetPaymentType =
  safeData.budget_payment_type ||
  (item.conversation_context || {}).budget_payment_type ||
  ctx.budget_payment_type ||
  null;

const budgetModeActive =
  typeof safeData.budget_mode_active === 'boolean'
    ? safeData.budget_mode_active
    : (
        typeof (item.conversation_context || {}).budget_mode_active === 'boolean'
          ? (item.conversation_context || {}).budget_mode_active
          : (
              typeof ctx.budget_mode_active === 'boolean'
                ? ctx.budget_mode_active
                : false
            )
      );

// ==============================
// CAMPOS COLETADOS DE AGENDAMENTO
// ==============================
const finalCustomerName =
  safeData.customer_name ||
  (item.conversation_context || {}).paciente_nome ||
  item.paciente_nome ||
  ctx.paciente_nome ||
  item.customer_name ||
  null;

const finalCustomerPhone =
  safeData.customer_phone ||
  (item.conversation_context || {}).customer_phone ||
  ctx.customer_phone ||
  item.customer_phone ||
  (item.phone_normalized ? `+${item.phone_normalized}` : null) ||
  null;

const finalTipoColeta =
  safeData.tipo_coleta ||
  (item.conversation_context || {}).tipo_coleta ||
  ctx.tipo_coleta ||
  null;

const finalEnderecoColeta =
  safeData.endereco_coleta ||
  (item.conversation_context || {}).endereco_coleta ||
  ctx.endereco_coleta ||
  null;

const finalDataPreferida =
  safeData.data_preferida ||
  (item.conversation_context || {}).data_preferida ||
  ctx.data_preferida ||
  null;

const finalHorarioPreferido =
  safeData.horario_preferido ||
  (item.conversation_context || {}).horario_preferido ||
  ctx.horario_preferido ||
  null;

// handoff deve refletir execução atual
const handoffRequiredNow = Boolean(resp.handoff);
const humanActiveNow = Boolean(resp.handoff);

const updated_context = {
  ...ctx,

  paciente_id: item.paciente_id || ctx.paciente_id || null,
  paciente_nome: finalCustomerName,
  customer_phone: finalCustomerPhone,

  last_message_at: new Date().toISOString(),
  last_intent: orch.intent || t.intent || ctx.last_intent || null,
  last_confidence: orch.confidence || t.confidence || ctx.last_confidence || null,

  last_exam_name_raw:
    (safeData.exame || {}).nome ||
    t.exam_name_raw ||
    (finalExamNamesList[0] || null) ||
    ctx.last_exam_name_raw ||
    null,

  last_exam_names_list:
    finalExamNamesList.length
      ? finalExamNamesList
      : (ctx.last_exam_names_list || []),

  budget_mode_active: budgetModeActive,

  budget_exam_names_list:
    finalBudgetExamNamesList.length
      ? finalBudgetExamNamesList
      : (ctx.budget_exam_names_list || []),

  budget_resolved_exams:
    finalBudgetResolvedExams.length
      ? finalBudgetResolvedExams
      : (ctx.budget_resolved_exams || []),

  budget_total_snapshot: budgetTotalSnapshot,
  budget_payment_type: budgetPaymentType,

  last_input_type: item.last_input_type || ctx.last_input_type || 'text',

  image_context_active: item.image_context_active || false,
  last_image_exams_text: item.image_exams_extracted || ctx.last_image_exams_text || '',
  last_image_exams_list: item.image_exams_list || ctx.last_image_exams_list || [],

  current_status: status,
  current_owner: resp.handoff ? 'human_queue' : (resp.subagent || 'ai_agent'),

  handoff_required: handoffRequiredNow,
  human_active: humanActiveNow,
  handoff_reason_codes: resp.reason_codes || [],

  collect_field:
    item.collect_field ||
    (item.conversation_context || {}).collect_field ||
    ctx.collect_field ||
    null,

  agendamento_etapa:
    (item.conversation_context || {}).agendamento_etapa ||
    ctx.agendamento_etapa ||
    null,

  tipo_coleta: finalTipoColeta,
  endereco_coleta: finalEnderecoColeta,
  data_preferida: finalDataPreferida,
  horario_preferido: finalHorarioPreferido,

  ambiguous_exam_query:
    (item.conversation_context || {}).ambiguous_exam_query ||
    ctx.ambiguous_exam_query ||
    null,

  ambiguous_exam_options:
    (item.conversation_context || {}).ambiguous_exam_options ||
    ctx.ambiguous_exam_options ||
    [],

  last_quoted_exams: quotedExams
};

return [{
  json: {
    ...item,
    updated_context
  }
}];

