const item    = $input.item.json;
const resp    = item.response || {};
const orch    = item.orchestration || {};
const config  = item.chatwoot_config || {};
const base    = String(config.base_url||'').trim().replace(/\/$/,'');
const accId   = String(config.account_id||'').trim();
const inboxId = String(config.inbox_id||'').trim();
const token   = String(config.api_token||'').trim();
const enabled = Boolean(base && accId && inboxId && token && !inboxId.includes('PREENCHER') && !token.includes('PREENCHER'));

const desired = resp.handoff ? 'pending' : 'open';
const extKey  = item.conversation_id || item.phone_normalized || 'unknown';
const note    = [
  'Resposta IA: ' + (resp.reply || 'N/A'),
  'Intent: ' + (orch.intent||'desconhecido'),
  'Decisão: ' + (orch.decision||'N/A'),
  resp.handoff ? 'HANDOFF: ' + (resp.handoff_category||'general') : null
].filter(Boolean).join('\n');

return [{ json: { ...item, chatwoot_sync: {
  enabled, base_url: base, account_id: accId,
  inbox_id: inboxId ? Number(inboxId) : null,
  api_token: token,
  external_key: extKey,
  customer_message: item.message_text || '',
  private_note: note,
  desired_status: desired,
  contact_payload: {
    inbox_id: inboxId ? Number(inboxId) : null,
    name: item.customer_name || 'Cliente WhatsApp',
    phone_number: item.customer_phone || '',
    identifier: 'wa:' + extKey,
    custom_attributes: { source: 'whatsapp', conversation_id: item.conversation_id }
  }
} } }];

