const sd   = $getWorkflowStaticData('global');
sd.chatwoot_maps = sd.chatwoot_maps || {};
const map  = sd.chatwoot_maps[item.chatwoot_sync.external_key] || null;
const hasCwIds = Boolean(map && map.conversation_id && map.contact_id);
return [{ json: {
  ...item,
  // Propaga IDs diretamente para compatibilidade com PATCH de atualização
  chatwoot_conversation_id: map ? map.conversation_id : null,
  chatwoot_contact_id:      map ? map.contact_id : null,
  chatwoot_state: {
    has_mapping:     hasCwIds,
    contact_id:      map ? map.contact_id : null,
    conversation_id: map ? map.conversation_id : null,
    inbox_id:        map ? map.inbox_id : item.chatwoot_sync.inbox_id,
    updated_at:      map ? map.updated_at : null
  }
} }];

const base  = $('Preparar Sync Chatwoot1').item.json;
const cont  = $('Criar Contato Chatwoot1').item.json || {};
const conv  = $input.item.json || {};
const sd    = $getWorkflowStaticData('global');
sd.chatwoot_maps = sd.chatwoot_maps || {};
const inboxId = Number(base.chatwoot_sync.inbox_id||0);
const ci = Array.isArray(cont.contact_inboxes) ? cont.contact_inboxes : [];
const m  = ci.find(x=>Number((x.inbox||{}).id)===inboxId)||ci[0]||{};
sd.chatwoot_maps[base.chatwoot_sync.external_key] = {
  contact_id: cont.id||null, conversation_id: conv.id||null,
  inbox_id: inboxId, updated_at: new Date().toISOString()
};
const chatwoot_contact_id     = cont.id || null;
const chatwoot_conversation_id = conv.id || null;
return [{ json: {
  ...base,
  chatwoot_contact_id,
  chatwoot_conversation_id,
  chatwoot_state: {
    has_mapping:     true,
    contact_id:      chatwoot_contact_id,
    conversation_id: chatwoot_conversation_id,
    inbox_id:        inboxId
  }
} }];

const body = $json.body || $json;
const data = body.data || {};
const key = data.key || {};
const msg = data.message || {};

const ev = String(body.event || '').toLowerCase();
const fromMe = Boolean(key.fromMe);

// ignora mensagens enviadas pela própria instância
if (fromMe) {
  return [];
}

// só trabalhamos com estes eventos
if (!['messages.upsert', 'messages.update'].includes(ev)) {
  return [];
}

// extrai texto
const text =
  msg.conversation ||
  msg.extendedTextMessage?.text ||
  msg.imageMessage?.caption ||
  msg.videoMessage?.caption ||
  msg.documentMessage?.caption ||
  '';

// detecta tipo
const messageType =
  data.messageType ||
  Object.keys(msg || {})[0] ||
  'unknown';

const isAudio = ['audioMessage', 'pttMessage'].includes(messageType);
const isImage = messageType === 'imageMessage';
const isDocument = messageType === 'documentMessage';

// mensagem válida precisa ter texto OU mídia suportada
const hasUsefulPayload =
  Boolean(String(text).trim()) || isAudio || isImage || isDocument;

if (!hasUsefulPayload) {
  return [];
}

// id base da mensagem
const baseMessageId =
  key.id ||
  data.key?.id ||
  `${key.remoteJid || 'unknown'}::${data.messageTimestamp || Date.now()}::${messageType}`;

// static data
const sd = $getWorkflowStaticData('global');
sd.processed_messages = sd.processed_messages || {};

// estrutura por mensagem
if (!sd.processed_messages[baseMessageId]) {
  sd.processed_messages[baseMessageId] = {
    upsert: false,
    update: false,
    created_at: Date.now()
  };
}

const record = sd.processed_messages[baseMessageId];

// REGRA OPERACIONAL:
// 1) processa upsert normalmente, uma única vez
// 2) update só processa se vier com payload útil e ainda não houve upsert
if (ev === 'messages.upsert') {
  if (record.upsert) {
    return [];
  }
  record.upsert = true;
}

if (ev === 'messages.update') {
  // se já teve upsert, ignora update
  if (record.upsert) {
    return [];
  }

  // se já processou update antes, ignora
  if (record.update) {
    return [];
  }

  record.update = true;
}

// limpeza para não crescer demais
const entries = Object.entries(sd.processed_messages);
if (entries.length > 5000) {
  const ordered = entries.sort((a, b) => {
    const ta = Number(a[1]?.created_at || 0);
    const tb = Number(b[1]?.created_at || 0);
    return ta - tb;
  });

  const toRemove = ordered.slice(0, entries.length - 3000);
  for (const [oldId] of toRemove) {
    delete sd.processed_messages[oldId];
  }
}

return [
  {
    json: {
      ...body
    }
  }
];
